  kniebeuge_kabel: ['Kniebeuge am Kabel', 'Seil oder Griff unten am Einzelkabelzug vor der Brust halten, einen Schritt zurück. In die Hocke und hochdrücken.', 'Cable Goblet Squat'],
  kniebeuge_doppel: ['Kniebeuge am Doppelkabelzug', 'Zwischen den Säulen des Doppelkabelzugs, Griffe unten an den Seiten. In die Hocke gehen und hochdrücken.', 'Functional Trainer Squat'],
  goblet_kniebeuge_pause: ['Goblet-Kniebeuge mit Pause', 'Kurzhantel vor der Brust, tief in die Hocke, unten 2 Sekunden halten, dann hochdrücken.', 'Paused Goblet Squat'],
  kniebeuge_fersen_erhoeht: ['Kniebeuge mit erhöhten Fersen', 'Fersen auf einer flachen Erhöhung, Kurzhanteln seitlich. Aufrecht tief beugen, Knie weit nach vorn.', 'Heel Elevated Squat'],
  cyclist_squat: ['Cyclist Squat', 'Füße eng, Fersen erhöht, Kurzhantel vor der Brust. Ganz aufrecht tief beugen, Knie weit nach vorn.', 'Cyclist Squat'],
  kniebeuge_box_kh: ['Box Squat (Kurzhantel)', 'Kurzhantel vor der Brust, kontrolliert auf einen Kasten setzen, kurz sitzen und aufstehen.', 'Goblet Box Squat'],
  hackenschmidt_rueckwaerts: ['Rückwärts-Hackenschmidt', 'Gesicht zum Polster an der Hackenschmidt-Maschine. Hüfte nach hinten, beugen und hochdrücken.', 'Reverse Hack Squat'],
  v_squat: ['V-Squat (Maschine)', 'Schultern unter die Polster der V-Squat-Maschine. Tief beugen und hochdrücken.', 'V Squat Machine'],
  beinpresse_sitzend: ['Sitzende Beinpresse (horizontal)', 'Aufrecht sitzen, Füße auf der Platte vor dir. Beine strecken und kontrolliert beugen, Knie nicht durchdrücken.', 'Seated Leg Press'],
  beinpresse_tief: ['Beinpresse (Füße tief)', 'Füße hüftbreit unten auf der Platte. Tief beugen und wegdrücken – mehr Oberschenkel vorn.', 'Low Foot Leg Press'],
  sumo_kniebeuge_kb: ['Sumo-Kniebeuge (Kettlebell)', 'Breiter Stand, Kettlebell hängt zwischen den Beinen. Tief beugen und hochdrücken.', 'Kettlebell Sumo Squat'],
  kniebeuge_pistol_box: ['Pistol Squat auf eine Box', 'Auf einem Bein, anderes Bein vorn. Kontrolliert auf eine Box setzen und einbeinig aufstehen. Seite wechseln.', 'Box Pistol Squat'],
  kniebeuge_shrimp: ['Shrimp Squat', 'Auf einem Bein, anderen Fuß hinten fassen. Hinteres Knie Richtung Boden senken und aufstehen. Seite wechseln.', 'Shrimp Squat'],
