  seitstuetz_abduktion: ['Seitstütz mit Beinheben', 'Seitstütz auf dem Unterarm, Körper gerade. Das obere Bein gestreckt anheben und senken, ohne dass die Hüfte absinkt.', 'Side Plank Leg Raise'],
  hip_airplane: ['Hip Airplane', 'Auf einem Bein, Oberkörper nach vorn geneigt. Becken langsam nach außen aufdrehen und wieder zurück, Hand bei Bedarf an der Wand.', 'Hip Airplane'],
  adduktion_liegend: ['Adduktion im Liegen', 'Seitenlage, oberes Bein vor dem Körper aufgestellt. Unteres Bein gestreckt vom Boden heben und langsam wieder ablegen.', 'Side Lying Hip Adduction'],
  adduktion_band: ['Adduktion im Stehen mit Band', 'Band seitlich verankert und um den inneren Knöchel. Bein gegen den Zug vor das Standbein führen, langsam zurück.', 'Standing Banded Adduction'],
  adduktoren_ball_druecken: ['Adduktoren-Drücken mit Ball', 'Rückenlage oder Sitz, Ball zwischen den Knien. Ball kräftig zusammendrücken, kurz halten und wieder lösen.', 'Ball Squeeze'],
  copenhagen_adduktion: ['Copenhagen-Adduktion', 'Seitstütz, oberer Fuß auf einer Bank, unteres Bein frei. Unteres Bein zur Bank heben und senken, die Hüfte bleibt oben.', 'Copenhagen Hip Adduction'],
  adduktion_gleiter: ['Seitlicher Ausfallschritt mit Gleiter', 'Ein Fuß auf einem Gleiter oder Handtuch. Bein seitlich wegschieben, im Standbein beugen, dann das Bein mit der Innenseite heranziehen.', 'Slider Lateral Lunge'],
  hueftbeuger_kabel: ['Hüftbeugen am Kabel', 'Rücken zum tiefen Kabel, Schlaufe am Knöchel. Knie gebeugt nach vorn oben ziehen, bis der Oberschenkel waagerecht ist.', 'Cable Hip Flexion'],
  hueftbeuger_band: ['Hüftbeugen mit Band', 'Band hinten verankert und um den Fuß. Knie im Stehen nach vorn hochziehen, oben kurz halten, langsam senken.', 'Banded Hip Flexion'],
  psoas_marsch_band: ['Psoas-Marsch mit Band', 'Rückenlage, Band um beide Fußsohlen, Beine angewinkelt in der Luft. Abwechselnd ein Knie zur Brust ziehen, das andere bleibt.', 'Banded Psoas March'],
  hueftbeuger_sitzend: ['Beinheben im Sitzen', 'Aufrecht sitzen, Beine gestreckt, Hände neben den Knien. Ein oder beide Beine ein paar Zentimeter vom Boden heben, ohne sich zurückzulehnen.', 'Seated Leg Lift'],
  knieheben_stehend_kh: ['Knieheben im Stehen (Kurzhantel)', 'Aufrecht stehen, Kurzhantel auf dem Oberschenkel festhalten. Knie über Hüfthöhe heben und langsam senken.', 'Standing Weighted Knee Raise'],
  wadenheben_lh: ['Wadenheben (Langhantel)', 'Langhantel auf dem oberen Rücken, Fußballen auf einer Scheibe. Fersen absenken und so hoch wie möglich drücken.', 'Barbell Calf Raise'],
  wadenheben_kb: ['Wadenheben (Kettlebell)', 'Kettlebells in den Händen, Fußballen auf einer Stufe. In voller Bewegung hoch und tief, oben kurz halten.', 'Kettlebell Calf Raise'],
  wadenheben_band: ['Wadendrücken mit Band', 'Im Langsitz, Band um die Fußballen. Fußspitzen gegen den Widerstand nach vorn strecken und langsam zurück.', 'Banded Calf Press'],
  wadenheben_stufe: ['Wadenheben auf der Stufe', 'Beide Fußballen auf einer Stufe, Fersen frei. Tief absenken bis zur Dehnung und ganz nach oben drücken.', 'Step Calf Raise'],
  wadenheben_einbeinig: ['Einbeiniges Wadenheben ohne Gewicht', 'Auf einem Fußballen auf der Stufe, an der Wand festhalten. Ferse tief senken und hochdrücken.', 'Single Leg Calf Raise'],
  wadenheben_hackenschmidt: ['Wadenheben an der Hackenschmidt-Maschine', 'Schultern unter die Polster, Fußballen an der Plattformkante. Knie fast gestreckt, Fersen senken und heben.', 'Hack Squat Calf Raise'],
  wadenheben_beinpresse_einbeinig: ['Einbeiniges Wadenheben an der Beinpresse', 'Nur ein Fußballen an der unteren Plattformkante. Knie fast gestreckt, Plattform mit dem Fußballen wegdrücken.', 'Single Leg Leg Press Calf Raise'],
  wadenheben_sitzend_kh: ['Wadenheben sitzend (Kurzhantel)', 'Auf der Bank sitzen, Fußballen auf einer Scheibe, Kurzhanteln auf den Knien. Fersen senken und heben.', 'Seated Dumbbell Calf Raise'],
  wadenheben_sitzend_einbeinig: ['Einbeiniges Wadenheben sitzend', 'An der Wadenmaschine nur ein Bein unter das Polster. Volle Bewegung, oben kurz anspannen.', 'Single Leg Seated Calf Raise'],
  wadenheben_smith_sitzend: ['Wadenheben sitzend (Smith-Maschine)', 'Bank unter die Smith-Stange, Stange gepolstert auf den Knien. Fußballen auf einer Stufe, Fersen heben und senken.', 'Smith Machine Seated Calf Raise'],
  wadenheben_pause: ['Wadenheben mit Pause', 'Wadenheben an der Maschine, unten in der Dehnung zwei Sekunden halten und oben eine Sekunde. Kein Federn.', 'Paused Calf Raise'],
  pogo_spruenge: ['Pogo-Sprünge', 'Kleine, schnelle Sprünge nur aus den Fußgelenken, Knie fast gestreckt. Kurzer Bodenkontakt auf den Fußballen.', 'Pogo Jumps'],
  tibialis_heben_kh: ['Schienbeinheben (Kurzhantel)', 'Auf der Bank sitzen, Kurzhantel zwischen den Füßen eingeklemmt. Fußspitzen hochziehen und langsam senken.', 'Dumbbell Tibialis Raise'],
  tibialis_band: ['Schienbeinziehen mit Band', 'Im Langsitz, Band vorn verankert und über dem Fußrücken. Fußspitzen zum Körper ziehen.', 'Banded Tibialis Raise'],
  kabelcrunch_stehend: ['Crunch am Kabel (stehend)', 'Rücken zum hohen Kabel, Seil neben dem Kopf halten. Oberkörper aus dem Bauch nach vorn unten einrollen, die Hüfte bleibt fast ruhig.', 'Standing Cable Crunch'],
